import { and, eq, sql } from 'drizzle-orm';
import * as s from '../db/company/schema/index.ts';
import type { DbOrTx } from '../db/provider.ts';
import { reserveNumber, peekNextNumber } from './sequences.ts';
import { saveEntry, type EntryInput, type SaveContext } from './journal.ts';

/**
 * Helpers for entries generated by automatic operations (AccountingHelper,
 * spec 02a 12): memorial orders of revaluation and closings, payment entries.
 */

async function documentNumberUsed(db: DbOrTx, documentTypeId: number, financialYearId: number, number: string) {
  const [r] = await db.select({ n: sql<number>`count(*)::int` }).from(s.accountings)
    .innerJoin(s.documents, eq(s.documents.id, s.accountings.documentId))
    .where(and(eq(s.accountings.financialYearId, financialYearId), eq(s.documents.documentTypeId, documentTypeId), eq(s.documents.number, number)));
  return (r?.n ?? 0) > 0;
}

async function channelOf(db: DbOrTx, documentTypeId: number) {
  const [t] = await db.select({ channel: s.documentTypes.sequenceChannel }).from(s.documentTypes).where(eq(s.documentTypes.id, documentTypeId));
  return t?.channel ?? 0;
}

/**
 * Next document number of a document type's sequence channel for the year
 * (e.g. МО channel 6, ПКО 4, РКО 5); '' when the type has no channel.
 */
export async function reserveDocumentNumber(db: DbOrTx, documentTypeId: number, financialYearId: number): Promise<string> {
  const channel = await channelOf(db, documentTypeId);
  if (!channel) return '';
  const r = await reserveNumber(db, channel, financialYearId, (n) => documentNumberUsed(db, documentTypeId, financialYearId, n));
  return r.number;
}

/** Next document number without reserving it (shown in a form). */
export async function peekDocumentNumber(db: DbOrTx, documentTypeId: number, financialYearId: number): Promise<string> {
  const channel = await channelOf(db, documentTypeId);
  return channel ? peekNextNumber(db, channel, financialYearId) : '';
}

/**
 * Saves a generated entry through the normal save path. A `documentNumber` of
 * undefined takes the next number of the document type's channel.
 */
export async function postSystemEntry(db: DbOrTx, input: Omit<EntryInput, 'documentNumber'> & { documentNumber?: string | null }, ctx: SaveContext) {
  let documentNumber = input.documentNumber;
  if (documentNumber === undefined && input.documentTypeId) documentNumber = await reserveDocumentNumber(db, input.documentTypeId, ctx.year.id);
  return saveEntry(db, { ...input, documentNumber: documentNumber ?? '' }, ctx);
}

/** Document type ids used by the automatic operations. */
export const MEMORIAL_ORDER = 10;
export const CASH_RECEIPT = 8;
export const CASH_PAYMENT = 9;
